var t=`0475-tabbouleh`;var i=`world-0475`;var o=`LB`;var r=`western-asia`;var a=4;var s=30;var l={en:`Tabbouleh`,ua:`Табуле`};var g={en:`A traditional dish from Lebanon, centered on parsley, mint, tomato, green onion. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ліван. Основні складники: петрушка, м'ята, помідор, зелена цибуля. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:13,i:[[`parsley`,180,`g`],[`mint`,35,`g`],[`tomato`,350,`g`],[`green-onion`,85,`g`]]},{en:`Cook the listed ingredients in simmering water for about 12 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 12 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:12,i:[[`bulgur`,75,`g`],[`water`,120,`ml`]]},{en:`Fold in the dressing ingredients, season to taste and serve, or chill briefly as appropriate.`,ua:`Обережно змішайте із заправкою, приправте до смаку й подавайте або трохи охолодіть за потреби.`,t:[`tossing`,`seasoning`],m:5,i:[[`extra-virgin-olive-oil`,70,`ml`],[`lemon-juice`,70,`ml`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var d={slug:t,id:i,country:`LB`,region:r,servings:4,minutes:30,title:l,text:g,steps:u};export{o as country,d as default,i as id,s as minutes,r as region,a as servings,t as slug,u as steps,g as text,l as title};